// Builds public/src/data/questions.js from data-src/questions.source.js, replacing each
// plain `correctAnswer` with an `answerCode` that only hashes to the right slot.
// Codes are derived deterministically so the generated file only changes when questions do.
import crypto from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { QUESTIONS } from '../data-src/questions.source.js';
import { answerSlot, ANSWER_TABLE_SIZE } from '../public/src/data/answerHash.js';

const OUT = new URL('../public/src/data/questions.js', import.meta.url);

function findCode(q) {
  for (let n = 0; n < 10_000; n++) {
    const code = crypto.createHash('sha256').update(`${q.question}:${n}`).digest('base64url').slice(0, 8);
    if (answerSlot(q.question, code) === q.correctAnswer) return code;
  }
  throw new Error(`No code found for: ${q.question}`);
}

const encoded = {};
let count = 0;
for (const [pool, list] of Object.entries(QUESTIONS)) {
  encoded[pool] = list.map((q) => {
    if (q.options.length !== ANSWER_TABLE_SIZE) throw new Error(`Need ${ANSWER_TABLE_SIZE} options: ${q.question}`);
    if (!Number.isInteger(q.correctAnswer) || q.correctAnswer < 0 || q.correctAnswer >= ANSWER_TABLE_SIZE) {
      throw new Error(`Bad correctAnswer: ${q.question}`);
    }
    const answerCode = findCode(q);
    if (answerSlot(q.question, answerCode) !== q.correctAnswer) throw new Error(`Verification failed: ${q.question}`);
    count++;
    return { question: q.question, options: q.options, answerCode };
  });
}

const body = Object.entries(encoded)
  .map(([pool, list]) => `  ${pool}: [\n${list.map((q) => `    ${JSON.stringify(q)},`).join('\n')}\n  ],`)
  .join('\n\n');

writeFileSync(
  OUT,
  `// GENERATED by scripts/encode-questions.js — do not edit.\n` +
    `// Edit data-src/questions.source.js and run \`npm run encode\`.\n` +
    `// The correct option index is answerSlot(question, answerCode), see answerHash.js.\n\n` +
    `export const QUESTIONS = {\n${body}\n};\n`,
);
console.log(`Encoded ${count} questions.`);
